from __future__ import annotations

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENT = Decimal("0.01")


def _numeric(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _rounded_cents(value: Any) -> Decimal:
    return _numeric(value).quantize(_CENT, rounding=ROUND_HALF_UP)


def _is_live(row: dict[str, Any]) -> bool:
    return row.get("DEL_FLG", "") != "Y"


def transition_invoiced(
    order: dict[str, Any], new_status: str
) -> tuple[dict[str, Any], list[str], list[str]]:
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated = dict(order)

    if new_status == "I":
        return updated, [], []

    if new_status == "X":
        updated["STAT_CD"] = "X"
        return updated, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        "E5003",
        "Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict[str, Any], lines: list[dict[str, Any]]
) -> tuple[dict[str, Any], list[dict[str, Any]], list[str]]:
    updated_order = dict(order)
    updated_lines = [dict(line) for line in lines]

    if order.get("STAT_CD") in ("I", "X"):
        return updated_order, updated_lines, []

    total = Decimal("0")

    for line in updated_lines:
        if not _is_live(line):
            continue

        ext_amt = _rounded_cents(
            _numeric(line.get("QTY", "")) * _numeric(line.get("UNIT_PRC", ""))
        )
        line["EXT_AMT"] = float(ext_amt)
        total += ext_amt

    discount = _numeric(order.get("DISC_PCT", ""))
    total_amount = (total * (Decimal("100") - discount) / Decimal("100")).quantize(
        _CENT, rounding=ROUND_HALF_UP
    )

    stored_total = _numeric(order.get("TOT_AMT", ""))
    audits = ["ORD_RETOTAL"] if stored_total != total_amount else []

    updated_order["TOT_AMT"] = float(total_amount)
    return updated_order, updated_lines, audits
